/// Wall clock the way `bsc mem build` prints the same figure, so the ack and the trend it points at
/// cannot disagree about units. Absent reads as absent — never as `0.0s`, for the reason [`Cost`] gives.
pub(crate) fn ack_ms(ms: Option<i64>) -> String {
    ms.map(|v| format!("{:.1}s", v as f64 / 1000.0)).unwrap_or_else(|| "time not measured".into())
}
